insert into public.events (id, status, speaker_name, talk, when_text, event_date, bio, note, photo_url, join_url) values
  ('f230629b-7fdd-52f2-a1e2-8363a54200d6', 'past', 'Christopher Dede', 'Preparing for a Future of Multiple Careers in the Age of AI', 'September 26th, 3 P.M. PST via Google Meet', '2026-09-26', 'Chris Dede is a Senior Research Fellow at the Harvard Graduate School of Education and was for 22 years the Timothy E. Wirth Professor in Learning Technologies. His fields of scholarship include emerging technologies, policy, and leadership. Chris is a Co-Principal Investigator and Associate Director for Research of the NSF-funded National Artificial Intelligence Institute in Adult Learning and Online Education. He is a Fellow of the American Educational Research Association, a Fellow of the Online Learning Consortium, a Scholar of the Immersive Learning Research Network, and a Distinguished Fellow of the Learning Engineering Network.
